    "mechanism": [
      "Πολυκατιονικά μόρια → περνούν την εξωτερική μεμβράνη από τις πορίνες → μεταφέρονται μέσα από την κυτταροπλασματική μεμβράνη με μηχανισμό που εξαρτάται από το οξυγόνο και το δυναμικό της μεμβράνης (αναστέλλεται από αναερόβιες συνθήκες, χαμηλό pH, υπερωσμωτικότητα, ασβέστιο και μαγνήσιο) → δέσμευση στο 16S rRNA της υπομονάδας 30S, στη θέση Α → το ριβόσωμα «διαβάζει» λάθος το mRNA → πρωτεΐνες με λάθος αμινοξέα ενσωματώνονται στη μεμβράνη και ανοίγουν πόρους → μαζική είσοδος φαρμάκου → πλήρης και μη αντιστρεπτή διακοπή της πρωτεϊνοσύνθεσης → θάνατος (μοντέλο Davis)."
    ],
