    "brands_str": "FUROLIN, NITROFURANTOIN/IASIS, όλα τα σκευάσματα στον Γαληνό",
    "mechanism": [
      "Προφάρμακο → οι βακτηριακές νιτροαναγωγάσες (φλαβοπρωτεΐνες) ανάγουν τη νιτρο-ομάδα → δραστικά ηλεκτρονιόφιλα ενδιάμεσα → ομοιοπολική βλάβη σε ριβοσωμικές πρωτεΐνες, DNA, ένζυμα του κύκλου του Krebs και της σύνθεσης του τοιχώματος → πολλαπλοί στόχοι ταυτόχρονα → η αντοχή απαιτεί πολλές μεταλλάξεις και παραμένει σπάνια μετά από 70 χρόνια χρήσης."
    ],
    "indications": [
      "Οξεία μη επιπλεγμένη κυστίτιδα, και σε γυναίκα με πρόσφατη λήψη κοτριμοξαζόλης ή κινολόνης.",
      "Προφύλαξη υποτροπών (6–12 μήνες)."
    ],
    "contraindications": [
      "Νεφρική ανεπάρκεια, έλλειψη G6PD, τέλος κύησης."
    ],
    "adverse_effects": [
      "Ναυτία, πνευμονίτιδα, ηπατίτιδα, νευροπάθεια, αιμόλυση."
    ],
