    "mechanism": [
      "Τα βακτήρια δεν προσλαμβάνουν έτοιμο φυλλικό: το συνθέτουν από πτεριδίνη, PABA και γλουταμινικό· τα ανθρώπινα κύτταρα το παίρνουν από την τροφή και δεν έχουν το πρώτο ένζυμο → εκλεκτική τοξικότητα.",
      "Σουλφοναμίδη = δομικό ανάλογο του PABA → συναγωνιστική αναστολή της συνθάσης του διυδροπτεροϊκού → ↓ διυδροφυλλικό. Τριμεθοπρίμη = ανάλογο του φυλλικού → αναστολή της βακτηριακής DHFR (συγγένεια περίπου 50.000 φορές μεγαλύτερη από ό,τι για το ανθρώπινο ένζυμο) → ↓ τετραϋδροφυλλικό → δεν συντίθενται θυμιδυλικό, πουρίνες, μεθειονίνη → διακοπή σύνθεσης DNA.",
      "Διαδοχικός αποκλεισμός δύο βημάτων της ίδιας οδού → συνέργεια: καθένα μόνο του είναι βακτηριοστατικό, ο συνδυασμός συχνά βακτηριοκτόνος, και η αντοχή απαιτεί δύο ταυτόχρονες μεταλλάξεις.",
      "Αντοχή: υπερπαραγωγή PABA, τροποποιημένη συνθάση ή DHFR με χαμηλή συγγένεια (πλασμιδιακά γονίδια sul και dfr), μειωμένη διαπερατότητα."
    ],
    "indications": [
      "Πνευμονία από Pneumocystis jirovecii: θεραπεία και προφύλαξη (φάρμακο εκλογής).",
      "Κυστίτιδα και πυελονεφρίτιδα με αντιβιόγραμμα, προστατίτιδα, προφύλαξη υποτροπών.",
      "Λοιμώξεις δέρματος και μαλακών μορίων από MRSA της κοινότητας.",
      "Stenotrophomonas maltophilia, Nocardia, Listeria (σε αλλεργία στην αμπικιλλίνη), τοξοπλάσμωση (προφύλαξη και εναλλακτική θεραπεία), ισοσπορίαση, κυκλοσπορίαση.",
      "Σαλμονέλλωση, σιγκέλλωση, παρόξυνση χρόνιας βρογχίτιδας από ευαίσθητα στελέχη."
    ],
    "contraindications": [
      "Αλλεργία στις σουλφοναμίδες.",
      "Τελευταίο τρίμηνο της κύησης και βρέφη κάτω των 2 μηνών (πυρηνικός ίκτερος)· πρώτο τρίμηνο (ανταγωνισμός φυλλικού).",
      "Έλλειψη G6PD.",
      "Μεγαλοβλαστική αναιμία από έλλειψη φυλλικού, σοβαρή νεφρική ή ηπατική ανεπάρκεια."
    ],
    "adverse_effects": [
      "Εξανθήματα, από ήπια κηλιδοβλατιδώδη έως σύνδρομο Stevens–Johnson και τοξική επιδερμική νεκρόλυση (πολύ συχνότερα στη λοίμωξη HIV).",
      "Μυελοκαταστολή: μεγαλοβλαστική αναιμία, λευκοπενία, θρομβοπενία· αιμόλυση σε έλλειψη G6PD.",
      "Υπερκαλιαιμία (η τριμεθοπρίμη αποκλείει τον δίαυλο νατρίου του αθροιστικού σωληναρίου, όπως η αμιλορίδη) και αύξηση της κρεατινίνης χωρίς πτώση της σπειραματικής διήθησης (αναστολή της σωληναριακής έκκρισής της).",
      "Κρυσταλλουρία, διάμεση νεφρίτιδα, ηπατίτιδα, φωτοευαισθησία.",
      "Πυρηνικός ίκτερος στα νεογνά (εκτόπιση της χολερυθρίνης από τη λευκωματίνη)."
    ],
    "pearls": [
      "Αναλογία στο δισκίο 1:5 (τριμεθοπρίμη προς σουλφαμεθοξαζόλη) → στο πλάσμα 1:20, η βέλτιστη για συνέργεια.",
      "Η τριμεθοπρίμη, πιο λιπόφιλη και ασθενής βάση, συγκεντρώνεται στο όξινο προστατικό και κολπικό υγρό.",
      "Δεν δίνεται εμπειρικά στην ουρολοίμωξη όταν η τοπική αντοχή του Escherichia coli ξεπερνά το 20% (Ελλάδα περίπου 19%) ή όταν ο ασθενής την πήρε το προηγούμενο τρίμηνο: ο ισχυρότερος παράγοντας κινδύνου αντοχής.",
      "Αλληλεπιδράσεις: ενισχύει βαρφαρίνη, σουλφονυλουρίες, φαινυτοΐνη, μεθοτρεξάτη (πανκυτταροπενία)· υπερκαλιαιμία με αναστολείς του μετατρεπτικού ενζύμου και σπιρονολακτόνη.",
      "Το φυλλινικό οξύ αναστρέφει τη μυελοτοξικότητα χωρίς να μειώνει τη δράση (τα βακτήρια δεν το προσλαμβάνουν).",
      "Δεν καλύπτει Pseudomonas, εντεροκόκκους, αναερόβια, ούτε αξιόπιστα τον Streptococcus pyogenes.",
      "Λάθος των διαφανειών: εμπειρική κοτριμοξαζόλη σε ασυμπτωματική βακτηριουρία διαβητικού."
    ],
